static void convin_45(const double* x0){
  for(int f=0;f<91125;f++){
    int sp = SPOS45[f];
    _mm_prefetch((const char*)(S45_re + SPOS45[f+24 < 91125 ? f+24 : f]), _MM_HINT_T0);
    _mm_prefetch((const char*)(S45_im + SPOS45[f+24 < 91125 ? f+24 : f]), _MM_HINT_T0);
    S45_re[sp] = x0[2*f];
    S45_im[sp] = x0[2*f+1];
  }
}
static void convc_45(const double* c){
  for(int f=0;f<91125;f++){
    int tp = TPOS45[f];
    _mm_prefetch((const char*)(CT45_re + TPOS45[f+24 < 91125 ? f+24 : f]), _MM_HINT_T0);
    _mm_prefetch((const char*)(CT45_im + TPOS45[f+24 < 91125 ? f+24 : f]), _MM_HINT_T0);
    CT45_re[tp] = c[2*f];
    CT45_im[tp] = c[2*f+1];
  }
}
static void convout_45(double* out){
  for(int f=0;f<91125;f++){
    int sp = SPOS45[f];
    _mm_prefetch((const char*)(S45_re + SPOS45[f+24 < 91125 ? f+24 : f]), _MM_HINT_T0);
    _mm_prefetch((const char*)(S45_im + SPOS45[f+24 < 91125 ? f+24 : f]), _MM_HINT_T0);
    out[2*f]   = S45_re[sp];
    out[2*f+1] = S45_im[sp];
  }
}
uint64_t bench_45(int which, long reps){
  uint64_t t0 = __rdtsc();
  for(long r=0;r<reps;r++){ if(which==0) phaseA_45(); else phaseB_45(); }
  return __rdtsc() - t0;
}
void run_45(const double* x0, const double* c, double* one, double* fin, long B, long m){
  for(long b=0;b<B;b++){
    convin_45(x0 + b*2*91125);
    convc_45(c + b*2*91125);
    for(long s=0;s<m;s++){
      phaseA_45();
      phaseB_45();
      if(s==0) convout_45(one + b*2*91125);
    }
    convout_45(fin + b*2*91125);
  }
}
